:root {
  --background: #f7f5f0;
  --foreground: #2c302d;
  --card: #fffefa;
  --primary: #28645b;
  --primary-foreground: #ffffff;
  --muted: #eeece5;
  --muted-foreground: #64685f;
  --border: #deded3;
  --input: #bcbfb3;
  --ring: #36796d;
  --accent: #e5efe8;
  --accent-foreground: #24574e;
  --destructive: #a33d37;
  --radius-card: 20px;
  --radius-control: 12px;
  --font-sans: "Segoe UI", "Helvetica Neue", Arial, sans-serif;
}
*{box-sizing:border-box}body{margin:0;background:var(--background);color:var(--foreground);font-family:var(--font-sans);font-size:16px;line-height:1.6}main{max-width:1040px;margin:auto;padding:32px}header{margin-bottom:24px}.eyebrow{font-size:12px;font-weight:600;letter-spacing:1px;color:var(--primary)}h1{font-size:30px;letter-spacing:-1px;margin:12px 0;line-height:1.2}p{color:var(--muted-foreground);line-height:1.65}h2{font-size:18px;margin:0 0 18px}.notice{background:var(--accent);padding:12px 16px;border-radius:var(--radius-control);font-size:14px;color:var(--accent-foreground);margin-bottom:22px}.metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(145px,1fr));gap:16px;margin-bottom:22px}.metric,.panel{background:var(--card);border:1px solid var(--border);border-radius:var(--radius-card);box-shadow:0 4px 16px #303b2b08}.metric{padding:20px}.metric span{font-size:14px;color:var(--muted-foreground)}.metric strong{display:block;font-size:26px;font-weight:600;margin-top:12px;font-variant-numeric:tabular-nums}.panel{padding:24px;margin-bottom:20px;min-width:0}#table{overflow:auto}table{width:100%;border-collapse:collapse}td,th{padding:12px 8px;border-bottom:1px solid var(--border);text-align:left;font-size:14px}th{color:var(--muted-foreground);font-weight:600}td:not(:first-child){font-variant-numeric:tabular-nums}.bar-row{display:flex;align-items:center;gap:12px;margin:14px 0}.bar-label{min-width:80px;font-size:14px}.bar-track{flex:1;background:var(--muted);height:12px;border-radius:6px;overflow:hidden}.bar{height:100%;background:var(--primary)}.bar-value{width:65px;text-align:right;font-size:14px;font-variant-numeric:tabular-nums}svg{width:100%;height:160px}textarea{width:100%;min-height:210px;padding:14px;border:1px solid var(--input);background:var(--background);color:var(--foreground);border-radius:var(--radius-control);font:16px/1.6 monospace;resize:vertical}button{background:var(--primary);color:var(--primary-foreground);border:0;border-radius:var(--radius-control);min-height:40px;padding:10px 16px;cursor:pointer;font-size:14px;font-family:var(--font-sans)}button:hover:not(:disabled){filter:brightness(.92)}button:disabled{opacity:.5;cursor:default}button:focus-visible,textarea:focus-visible,summary:focus-visible{outline:2px solid var(--ring);outline-offset:3px}#save{margin-top:12px}.explain-head{display:flex;flex-wrap:wrap;gap:12px;justify-content:space-between;align-items:baseline}summary{cursor:pointer;font-weight:600;min-height:40px}footer{font-size:12px;color:var(--muted-foreground);padding:8px 0}#error{color:var(--destructive);white-space:pre-wrap;overflow-wrap:anywhere}@media(max-width:550px){main{padding:16px}h1{font-size:25px}.metrics{grid-template-columns:1fr 1fr}.panel{padding:18px}.metric{padding:16px}}

